\title{A Diophantine Sufficient Condition for Strong Aperiodicity of Wang Stripe Sets}
\author{Aristotle}
\date{June 28, 2026}

\begin{document}

\begin{abstract}
We study a quantitative refinement of the classical fact that irrational densities force
aperiodicity in stripe-based Wang tile families. Working with the Beatty-stripe skeleton
$W(\alpha,\beta)$ of a two-dimensional Wang tile set --- vertical stripes of density $\alpha$
overlaid on horizontal stripes of density $\beta$ --- we replace the qualitative hypothesis
``$\alpha,\beta$ irrational'' by the sharp, falsifiable hypothesis ``$\alpha,\beta$ Diophantine,''
meaning each density admits a uniform separation $|\alpha - a/b| \ge c/b^2$ from every rational
$a/b$. We prove that every Diophantine real is irrational; that every irrational square root
$\sqrt{d}$ is Diophantine with explicit constant $c = 1/(2\sqrt{d}+1)$ via the surd identity
$|\sqrt{d}-a/b|\cdot|\sqrt{d}+a/b| = |d b^2 - a^2|/b^2$ and the nonzero-integer bound
$|d b^2 - a^2| \ge 1$; that for $\sqrt 2$ the constant improves to $1/4$; and that a Diophantine
pair certifies strong aperiodicity of $W(\alpha,\beta)$, instantiated at the quadratic pair
$(\sqrt 2, \sqrt 3)$. The Diophantine exponent $2$ emerges as the structural invariant --- the
algebraic signature of degree-two irrationality. We discuss algorithms, applications to aperiodic
order, and a program of conjectures (necessity, exponent-optimality, complexity-rate control).
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Background}
A \emph{Wang tile} is a unit square with a color assigned to each of its four edges. Given a finite
set of Wang tiles, a \emph{tiling} of the plane assigns one tile (without rotation or reflection) to
each cell of $\Z^2$ so that adjacent tiles share the color along their common edge. A tiling is
\emph{periodic} if some nonzero $v \in \Z^2$ leaves it invariant under translation, and
\emph{strongly aperiodic} if it admits no nonzero period vector at all. A tile set is \emph{aperiodic}
if it tiles the plane but only aperiodically. Wang conjectured that any tile set able to tile the plane
could do so periodically; Berger refuted this, launching the modern theory of aperiodic order, the
mathematical backbone of physical quasicrystals. A clean source of aperiodicity is irrationality of a
density parameter: a tiling encoding a non-rational density admits no exact repetition.

\subsection{The stripe skeleton}
For $\alpha \in \R$ the \emph{Beatty step word} is
\[
d_\alpha(n) = \floor{(n+1)\alpha} - \floor{n\alpha}, \qquad n \in \N.
\]
For $\alpha \in (0,1)$ this is the binary Sturmian word of slope $\alpha$, with telescoping identity
$\sum_{n<N} d_\alpha(n) = \floor{N\alpha}$, so the frequency of $1$'s equals $\alpha$ and eventual
periodicity is pinned to the arithmetic of $\alpha$. The \emph{Wang stripe set} $W(\alpha,\beta)$
overlays vertical stripes governed by $d_\alpha$ on horizontal stripes governed by $d_\beta$; it is the
skeleton of a Wang tile set whose edge colors encode the stripe positions. The governing geometric
principle is: $W(\alpha,\beta)$ admits a nonzero period vector iff one of $d_\alpha, d_\beta$ is
eventually periodic, and $d_\gamma$ is periodic iff $\gamma \in \Q$; hence both densities irrational
implies $W(\alpha,\beta)$ strongly aperiodic. We take this criterion as geometric input and supply the
quantitative number-theoretic input.

\subsection{Contribution}
``Irrational'' certifies the pattern never exactly repeats but says nothing about how closely it
approaches repetition. We sharpen it to the \emph{Diophantine} condition (badly approximable to
exponent $2$) and prove the chain
\[
\text{Diophantine } \alpha \wedge \beta \;\Rightarrow\; \text{Irrational } \alpha,\beta \;\Rightarrow\;
\text{no period of } d_\alpha, d_\beta \;\Rightarrow\; \text{strong aperiodicity of } W(\alpha,\beta),
\]
with all constants explicit and all hypotheses witnessed by the surds $\sqrt 2, \sqrt 3$.

\section{Definitions}

\begin{definition}[Diophantine real]
A real $\alpha$ is \emph{Diophantine} (badly approximable to exponent $2$) if there is a constant
$c > 0$ with
\[
\frac{c}{b^2} \le \left| \alpha - \frac{a}{b} \right| \qquad \text{for all } a \in \Z,\; b \in \N,\; b \ge 1.
\]
Any such $c$ is a \emph{separation constant}.
\end{definition}

By Dirichlet's theorem infinitely many fractions satisfy $|\alpha - a/b| < 1/b^2$; the Diophantine
condition asserts a matching lower bound, so badly approximable numbers sit exactly at this threshold.

\begin{definition}[Irrational]
$\alpha$ is irrational if $\alpha \neq q$ for every $q \in \Q$.
\end{definition}

\begin{definition}[Beatty step word; stripe set; aperiodicity]
$d_\alpha(n) = \floor{(n+1)\alpha} - \floor{n\alpha}$. $W(\alpha,\beta)$ is the configuration whose
vertical (resp.\ horizontal) stripe positions are the support of $d_\alpha$ (resp.\ $d_\beta$). It is
\emph{strongly aperiodic} if no nonzero $v \in \Z^2$ satisfies $W(\alpha,\beta) + v = W(\alpha,\beta)$.
\end{definition}

\section{Diophantine implies irrational}

\begin{theorem}[\texttt{Diophantine\_irrational}]
If $\alpha$ is Diophantine, then $\alpha$ is irrational.
\end{theorem}

\begin{proof}[Proof sketch]
Let $c>0$ be a separation constant and suppose $\alpha = q \in \Q$, written $q = a/b$ with $b \ge 1$.
Applying the definition to this $a/b$ gives $0 < c/b^2 \le |\alpha - a/b| = 0$, a contradiction. A
rational density is hit exactly by one competing fraction, violating any positive lower bound.
\end{proof}

\section{Quadratic irrationals are Diophantine}

\subsection{The surd identity}
For $d \in \N$ with $\sqrt d$ irrational and any $a/b$ ($b \ge 1$),
\begin{equation}
\left|\sqrt d - \tfrac{a}{b}\right| \cdot \left|\sqrt d + \tfrac{a}{b}\right|
= \left| d - \tfrac{a^2}{b^2}\right| = \frac{|d\,b^2 - a^2|}{b^2}.
\end{equation}
The numerator $d b^2 - a^2$ is a nonzero integer (else $\sqrt d = |a|/b \in \Q$), so $|d b^2 - a^2| \ge 1$ and
\begin{equation}
\left|\sqrt d - \tfrac{a}{b}\right| \cdot \left|\sqrt d + \tfrac{a}{b}\right| \ge \frac{1}{b^2}.
\end{equation}
This single integrality constraint is the engine of the result and the algebraic signature of degree two.

\begin{theorem}[\texttt{sqrt\_Diophantine}]
If $d \in \N$ and $\sqrt d$ is irrational, then $\sqrt d$ is Diophantine with separation constant
$c = 1/(2\sqrt d + 1)$.
\end{theorem}

\begin{proof}[Proof sketch]
Fix $a,b$ and put $c = 1/(2\sqrt d + 1) > 0$. If $|\sqrt d - a/b| < 1$, then $a/b$ is within $1$ of
$\sqrt d \ge 1$, so $|\sqrt d + a/b| < 2\sqrt d + 1$, and combining with the product bound gives
$|\sqrt d - a/b| \ge (1/b^2)/(2\sqrt d+1) = c/b^2$. If instead $|\sqrt d - a/b| \ge 1$, then since
$c \le 1$ and $b \ge 1$ we get $c/b^2 \le 1 \le |\sqrt d - a/b|$. In both cases $c/b^2 \le |\sqrt d - a/b|$.
\end{proof}

\begin{theorem}[\texttt{sqrt\_two\_Diophantine}, \texttt{sqrt\_three\_Diophantine}]
$\sqrt 2$ and $\sqrt 3$ are Diophantine, with constants $1/(2\sqrt2+1) \approx 0.261$ and
$1/(2\sqrt3+1) \approx 0.225$ respectively.
\end{theorem}

\begin{proof}[Proof sketch]
$\sqrt 2$ is irrational (classical) and $\sqrt 3$ is irrational ($3$ prime); apply the previous theorem
with $d = 2$ and $d = 3$.
\end{proof}

\begin{theorem}[\texttt{sqrt\_two\_diophantine\_quarter}]
For all $a \in \Z$ and $b \ge 1$,
\[
\frac{1}{4 b^2} \le \left|\sqrt 2 - \frac{a}{b}\right|.
\]
\end{theorem}

\begin{proof}[Proof sketch]
The nonzero integer $a^2 - 2b^2$ (nonzero since $a^2 = 2b^2$ would give $a/b = \pm\sqrt2$) satisfies
$|a^2 - 2b^2| \ge 1$, so $|\sqrt 2 - a/b|\cdot|\sqrt 2 + a/b| \ge 1/b^2$. If $|\sqrt 2 - a/b| < 1$ then
$\sqrt2 + a/b < 2\sqrt2 + 1 < 4$, whence $|\sqrt 2 - a/b| \ge 1/(4b^2)$; otherwise
$|\sqrt 2 - a/b| \ge 1 \ge 1/(4b^2)$.
\end{proof}

\section{From Diophantine pairs to strong aperiodicity}

\begin{theorem}[\texttt{diophantine\_pair\_aperiodic}]
If $\alpha$ and $\beta$ are both Diophantine, then $W(\alpha,\beta)$ is strongly aperiodic.
\end{theorem}

\begin{proof}[Proof sketch]
Each density is irrational by Theorem~3.1; by the aperiodicity criterion, irrationality of $\gamma$
makes $d_\gamma$ non-periodic, and a nonzero period vector of $W(\alpha,\beta)$ would force periodicity
of $d_\alpha$ or $d_\beta$. Hence no nonzero period vector exists.
\end{proof}

\begin{theorem}[\texttt{sqrt2\_sqrt3\_wang\_aperiodic}]
$W(\sqrt 2, \sqrt 3)$ is strongly aperiodic.
\end{theorem}

\begin{proof}[Proof sketch]
Combine the two surd theorems with the linking theorem; the joint separation constant is
$\min\{1/(2\sqrt2+1), 1/(2\sqrt3+1)\} = 1/(2\sqrt3+1) \approx 0.225$.
\end{proof}

\section{Algorithms and numerical verification}

\textbf{Beatty step word generator.} Compute $d_\alpha(n)$ for $n < N$; periods of length $b$ appear iff
$\alpha = a/b$ in lowest terms. Complexity $O(N)$.

\textbf{Diophantine bound certifier.} For $b = 1,\dots,B$ the only candidate violator is
$a = \mathrm{round}(b\sqrt d)$; verify $|\sqrt d - a/b| \ge c/b^2$. Complexity $O(B)$.

\textbf{Convergent stress test.} Continued-fraction convergents $p_k/q_k$ are the worst approximators;
the normalized error $q_k^2 |\sqrt d - p_k/q_k|$ stays above the separation constant, confirming the
exponent $2$ scale. Complexity $O(K)$.

\section{Discussion and future directions}

The exponent $2$ is the algebraic degree of a square root, surfacing through the quadratic numerator
$d b^2 - a^2$; cubic irrationals and Liouville numbers break the nonzero-integer step (Liouville numbers
are irrational but not Diophantine of exponent $2$). Applications include aperiodic order and
quasicrystals, symbolic dynamics of badly approximable slopes, and constructive verification.

\begin{conjecture}[Necessity]
For every real $\alpha$, $d_\alpha$ is eventually periodic iff $\alpha \in \Q$; its minimal period equals
the denominator of $\alpha$ in lowest terms.
\end{conjecture}

\begin{conjecture}[Exponent-optimality]
The slopes whose Diophantine exponent $2$ is optimal are exactly the quadratic irrationals; slopes with
unbounded continued fraction admit no uniform $c/b^2$ bound.
\end{conjecture}

\begin{conjecture}[Complexity rate]
With $c(\alpha,\beta) = \min(c_\alpha,c_\beta)$, the pattern-complexity function $p(R)$ of $W(\alpha,\beta)$
grows like $\Theta(R^2)$ with implied constant monotone in $1/c(\alpha,\beta)$; for a pair of quadratic
irrationals it is exactly $\Theta(R^2)$.
\end{conjecture}

We prove sufficiency, not necessity; the model is the Beatty stripe skeleton of a Wang set, and the
constant $1/4$ for $\sqrt 2$, while clean and uniform, is not asymptotically optimal.

\section{Conclusion}
Being Diophantine of exponent $2$ is a sharp, explicit, non-vacuous condition that strengthens
``irrational density'' and certifies strong aperiodicity of Wang stripe sets, witnessed concretely by
$W(\sqrt 2, \sqrt 3)$. The exponent $2$ is the algebraic fingerprint of degree-two irrationality, and the
explicit separation constants render aperiodicity a measurable, computable phenomenon.

\end{document}

