function BEATTY-STEP-WORD(alpha, N):
  for n = 0 .. N-1:
    w[n] <- floor((n+1)*alpha) - floor(n*alpha)
  return w

function SMALLEST-PERIOD(w):
  n <- length(w)
  for p = 1 .. floor(n/2):
    if w[i] == w[i+p] for all 0 <= i < n-p:
      return p          # period found
  return NONE             # no period: evidence of aperiodicity

